<script setup lang="ts">
import { computed, ref } from 'vue';
import type { DataSection, FeatureSummary, TaskSummary } from '../../../shared/api.js';
import StatusBadge from './StatusBadge.vue';
import SourceNotice from './SourceNotice.vue';
const props = defineProps<{ section: DataSection<TaskSummary>; features: DataSection<FeatureSummary> }>();
const feature = ref(''), query = ref(''), selectedId = ref<string | null>(null);
const featureIds = computed(() => [...new Set([...props.features.items.map(item => item.id), ...props.section.items.map(item => item.featureId)])].sort());
const filtered = computed(() => props.section.items.filter(task => (!feature.value || task.featureId === feature.value) && `${task.id} ${task.role} ${task.status}`.toLowerCase().includes(query.value.toLowerCase())).sort((a,b) => a.id.localeCompare(b.id)));
const selected = computed(() => filtered.value.find(task => task.id === selectedId.value) ?? filtered.value[0]);
</script>
<template><section class="card panel"><div class="panel-heading"><div><h2>Tasks &amp; checkpoints</h2><p class="muted">Persisted task state is distinct from verified live execution.</p></div><div class="filters"><label>Feature<select v-model="feature"><option value="">All features</option><option v-for="id in featureIds" :key="id" :value="id">{{ id }}</option></select></label><label>Filter tasks<input v-model="query" type="search" placeholder="Task, role, state" /></label></div></div><SourceNotice :source="section.source" /><SourceNotice v-if="features.source.status !== 'ok'" :source="features.source" /><p v-if="!filtered.length" class="empty-state">{{ section.items.length ? 'No tasks match these filters.' : 'No validated task records are available.' }}</p><div v-else class="task-layout"><div class="table-scroll"><table><thead><tr><th>Task / feature</th><th>State</th><th>Progress</th><th>Launches</th></tr></thead><tbody><tr v-for="task in filtered" :key="task.id" :class="{ selected: selected?.id === task.id }"><td><button class="task-link" @click="selectedId = task.id">{{ task.id }}</button><small class="cell-hint">{{ task.featureId }} · {{ task.role }}</small></td><td><StatusBadge :status="task.status" /><small v-if="task.state !== task.status" class="cell-hint">Persisted: {{ task.state }}</small></td><td>{{ task.completedSteps == null ? 'Unknown' : `${task.completedSteps.length} / ${task.steps.length}` }}<small class="cell-hint">{{ task.activeStep ?? (task.waitingOn.length ? `Waiting on ${task.waitingOn.join(', ')}` : 'No verified active step') }}</small></td><td>{{ task.launches ?? '—' }}<small class="cell-hint">Failure attempts: {{ task.failureAttempts ?? 'unknown' }}</small></td></tr></tbody></table></div><aside v-if="selected" class="task-detail"><span class="eyebrow">TASK DETAILS</span><h3>{{ selected.id }}</h3><p v-if="selected.reason" class="source-notice warning">{{ selected.reason }}</p><dl><div><dt>Last recorded provider</dt><dd>{{ selected.provider ?? 'Unknown' }}</dd></div><div><dt>Recorded requested model</dt><dd>{{ selected.requestedModel ?? 'Not verified' }}</dd></div><div><dt>Dependencies</dt><dd>{{ selected.dependsOn.join(', ') || 'None recorded' }}</dd></div><div><dt>Next attempt (UTC)</dt><dd>{{ selected.nextAttemptAt ?? 'Not scheduled / unknown' }}</dd></div><div><dt>Live task identity</dt><dd>{{ selected.liveIdentityVerified ? 'Verified' : 'Not verified' }}</dd></div></dl><SourceNotice :source="selected.source" /><h3>Checkpoint history</h3><SourceNotice :source="selected.checkpointSource" /><p v-if="!selected.checkpoints.length" class="muted">No validated checkpoints for this task.</p><ol v-else class="timeline"><li v-for="checkpoint in selected.checkpoints" :key="checkpoint.id"><div><strong>#{{ checkpoint.sequence }} · {{ checkpoint.step }}</strong><StatusBadge :status="checkpoint.status" /></div><p>{{ checkpoint.commit ?? 'No commit' }} · {{ checkpoint.provider ?? 'Unknown provider' }} · requested {{ checkpoint.requestedModel ?? 'CLI default / unknown' }}</p><time>{{ checkpoint.at ?? 'Time unavailable' }}</time></li></ol><p class="source-meta">History is capped at 20 checkpoints per task and 400 across the snapshot. Completed steps include all validated retained source checkpoints.</p><SourceNotice :source="selected.schedulingSource" /></aside></div></section></template>
